from typing import Literal

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class SettingsMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.settings.get_api_settings_safety")
    def get_api_settings_safety(self):
        """
        Получение информации по активности антивируса
        Ручка для получения сведений о антивирусе для файлов, таких как режим работы, ключ, срок действия и т.д.
        :return: тело ответа сервера
        """
        return self.get("api/settings/safety")

    @tracer.start_as_current_span("admin.settings.post_api_settings_safety")
    def post_api_settings_safety(
        self,
        antivirus_enabled: bool,
        work_mode: Literal["sync", "async"],
        kspd_work_mode: str,
        dmz_work_mode: str,
        key_name: str,
        pin_enabled: bool,
    ):
        """
        Обновление сведений о антивирусе
        Настройка информации связанной с работой антивируса
        :param antivirus_enabled: boolean example: true Состояние антивируса вкл/выкл
        :param work_mode: string example: async Режим работы антивируса
        :param kspd_work_mode: string Название ключа антивируса
        :param dmz_work_mode: string Название ключа антивируса
        :param key_name: string Название ключа антивируса
        :param pin_enabled:	boolean Требовать включение пин-кода на устройстве
        :return: тело ответа сервера
        """
        return self.post(
            "api/settings/safety",
            data={
                "antivirus_enabled": antivirus_enabled,
                "work_mode": work_mode,
                "kspd_work_mode": kspd_work_mode,
                "dmz_work_mode": dmz_work_mode,
                "key_name": key_name,
                "pin_enabled": pin_enabled,
            },
        )

    @tracer.start_as_current_span("admin.settings.api_settings_safety_key")
    def api_settings_safety_key(self, key_name: str, key_value: str):
        """
        Проверка ключа антивируса
        По переданной паре ключ-значение проверяет ключ на активность
        :param key_name: string example: some name
        :param key_value: string example: secret_key
        :return: тело ответа сервера
        """
        return self.post(
            "api/settings/safety/key",
            data={"key_name": key_name, "key_value": key_value},
        )

    @tracer.start_as_current_span("admin.settings.api_settings_safety_disable_os")
    def api_settings_safety_disable_os(self, os_disable: list[str]):
        """
        Выключение автообновлений
        Выключить автообновления для операционных систем, переданных в запросе. Те ОС, что не указаны в теле,
        будут включены
        :param os_disable: example: List [ "android", "win_32", "ios" ] список операционных систем, которые
        необходимо выключить
        :return: тело ответа сервера
        """
        return self.post("api/settings/safety/disableOS", data={"os_disable": os_disable})

    @tracer.start_as_current_span("admin.settings.get_api_settings_network")
    def get_api_settings_network(self):
        """
        Настройки сети
        Получить настройки сети
        :return: тело ответа сервера
        """
        return self.get("api/settings/network")

    @tracer.start_as_current_span("admin.settings.post_api_settings_network")
    def post_api_settings_network(self, kspd: str, dmz: str):
        """
        Обновление сетевых настроек
        :param kspd: string example: kspd settings зона корпоративной сети передачи данных
        :param dmz:	string example: dmz settings демилитаризованная зона
        :return: тело ответа сервера
        """
        return self.post("api/settings/network", data={"kspd": kspd, "dmz": dmz})

    @tracer.start_as_current_span("admin.settings.get_api_settings_vip")
    def get_api_settings_vip(self):
        """
        Получение настроек для vip
        :return: тело ответа сервера
        """
        return self.get("api/settings/vip")

    @tracer.start_as_current_span("admin.settings.post_api_settings_vip")
    def post_api_settings_vip(
        self,
        ad_import_path_for_vip: str,
        ad_import_path_for_trusted: str,
        invisible_phone: bool,
        cannot_call_to_vip: bool,
    ):
        """
        Изменение настроек для vip
        :param invisible_phone:	boolean Не отображать номер телефона VIP пользователя
        :param cannot_call_to_vip	boolean Нельзя первым позвонить или написать VIP пользователю всем, кроме доверенных
        :param ad_import_path_for_vip:	string Путь к AD для vip
        :param ad_import_path_for_trusted:	string Путь к AD группе доверенных для vip лиц
        :return: тело ответа сервера
        """
        return self.post(
            "api/settings/vip",
            data={
                "invisible_phone": invisible_phone,
                "cannot_call_to_vip": cannot_call_to_vip,
                "ad_import_path_for_vip": ad_import_path_for_vip,
                "ad_import_path_for_trusted": ad_import_path_for_trusted,
            },
        )

    @tracer.start_as_current_span("admin.settings.get_api_settings_additional")
    def get_api_settings_additional(self):
        """
        Получение дополнительных настроек
        :return: тело ответа сервера
        """
        return self.get("api/settings/additional")

    @tracer.start_as_current_span("admin.settings.post_api_settings_additional")
    def post_api_settings_additional(self, supportEmails: list[str]):
        """
        Изменение дополнительных настроек
        :param supportEmails: Почта для отправки сообщений в krtek
        :return: тело ответа сервера
        """
        return self.post("api/settings/additional", data={"supportEmails": supportEmails})
